    const close = balanced(s, i);
    args = s.slice(i + 1, close - 1).trim();
    i = close;
  }
  let body = "";
  if (name !== SCENE_BREAK_FUNCTION) {

  if (name !== SCENE_BREAK_FUNCTION) {
