    expect(
      typstToHtml("= Title\n\nHello *bold* and _italic_.\n\n- First\n- Second"),
    ).toBe(
      "<h1>Title</h1><p>Hello <strong>bold</strong> and <em>italic</em>.</p><ul><li><p>First</p></li><li><p>Second</p></li></ul>",
    );
  });
