  }
  const settings = typstPageSetup(payload, originalSource);
  const appendices = serializeTypst({ ...payload, title: "", html: "" }).source;
  const notesAt = appendices.indexOf("#heading(level: 2)");
  return (
    settings +
    "\n" +
    source +
    (notesAt >= 0 ? "\n" + appendices.slice(notesAt) : "")
